import { type Provider } from '@angular/core';
import { provideBrnCalendarI18n } from '@spartan-ng/brain/calendar';

import type { WiWeekday } from './wi-datepicker.types';

/** Etiquetas de los 12 meses (índice 0 = enero). */
export type WiMonthLabels = [
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
];

/**
 * Configuración de locale del calendario (inyectable desde la app).
 * No hardcodear copy de producto en la librería.
 */
export interface WiCalendarI18n {
  formatWeekdayName: (index: number) => string;
  formatHeader: (month: number, year: number) => string;
  formatYear: (year: number) => string;
  formatMonth: (month: number) => string;
  labelPrevious: () => string;
  labelNext: () => string;
  labelWeekday: (index: number) => string;
  months: () => WiMonthLabels;
  years: (startYear?: number, endYear?: number) => number[];
  firstDayOfWeek: () => WiWeekday;
}

/**
 * Provee i18n del calendario para `wi-datepicker` (y cualquier calendario Brain hijo).
 *
 * @example
 * ```ts
 * provideWiCalendarI18n({
 *   firstDayOfWeek: () => 1,
 *   labelPrevious: () => 'Mes anterior',
 *   labelNext: () => 'Mes siguiente',
 * })
 * ```
 */
export function provideWiCalendarI18n(configuration?: Partial<WiCalendarI18n>): Provider {
  return provideBrnCalendarI18n(configuration);
}

export type WiIconVariant = 'outline' | 'solid';

/** Tamaño tipográfico del icono (clases Tailwind estáticas). */
export type WiIconSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

/**
 * Nombre de icono registrado.
 * Es `string` a propósito para permitir iconos personalizados de la app.
 */
export type WiIconName = string;

/** Etiquetas SVG permitidas al renderizar glyphs. */
export type WiSvgTag = 'path' | 'circle' | 'rect' | 'line' | 'polyline' | 'polygon' | 'g';

/**
 * Nodo SVG estructurado.
 * Solo se renderizan tags y atributos de la allowlist del componente.
 */
export interface WiSvgNode {
  readonly tag: WiSvgTag;
  readonly attrs: Readonly<Record<string, string>>;
  readonly children?: readonly WiSvgNode[];
}

/**
 * Representación tipada de un glifo SVG.
 * Preferible a strings HTML: sin innerHTML y compatible con SSR.
 */
export interface WiIconGlyph {
  readonly viewBox: string;
  readonly nodes: readonly WiSvgNode[];
  /**
   * Si es `true`, no se aplican defaults de `currentColor`
   * (útil para logos multicolor).
   */
  readonly preserveColors?: boolean;
}

/** Definición de un icono con una o ambas variantes. */
export interface WiIconDefinition {
  readonly outline?: WiIconGlyph;
  readonly solid?: WiIconGlyph;
}

/** Mapa nombre → definición para `provideWiIcons`. */
export type WiIconRegistry = Readonly<Record<string, WiIconDefinition>>;

export type WiIconVariant = 'outline' | 'solid';

/** Tamaño tipográfico del icono (clases Tailwind estáticas). */
export type WiIconSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

/**
 * Nombre de icono registrado.
 * Es `string` a propósito para permitir iconos personalizados de la app.
 */
export type WiIconName = string;

/** Etiquetas SVG permitidas al renderizar glyphs. */
export type WiSvgTag = 'path' | 'circle' | 'rect' | 'line' | 'polyline' | 'polygon' | 'g';

/**
 * Nodo SVG estructurado.
 * Solo se renderizan tags y atributos de la allowlist del componente.
 */
export interface WiSvgNode {
  readonly tag: WiSvgTag;
  readonly attrs: Readonly<Record<string, string>>;
  readonly children?: readonly WiSvgNode[];
}

/**
 * Representación tipada de un glifo SVG.
 * Preferible a strings HTML: sin innerHTML y compatible con SSR.
 */
export interface WiIconGlyph {
  readonly viewBox: string;
  readonly nodes: readonly WiSvgNode[];
  /**
   * Si es `true`, no se aplican defaults de `currentColor`
   * (útil para logos multicolor).
   */
  readonly preserveColors?: boolean;
}

/** Definición de un icono con una o ambas variantes. */
export interface WiIconDefinition {
  readonly outline?: WiIconGlyph;
  readonly solid?: WiIconGlyph;
}

/** Mapa nombre → definición para `provideWiIcons`. */
export type WiIconRegistry = Readonly<Record<string, WiIconDefinition>>;

import type { WiIconDefinition, WiIconRegistry, WiIconVariant } from './wi-icon.types';

/**
 * Combina varios registros.
 * Orden: el último gana por nombre; dentro de un nombre se hace merge de variantes.
 */
export function mergeIconRegistries(
  registries: readonly WiIconRegistry[] | null | undefined,
): WiIconRegistry {
  if (!registries?.length) {
    return {};
  }

  const merged: Record<string, WiIconDefinition> = {};

  for (const registry of registries) {
    for (const [name, definition] of Object.entries(registry)) {
      const existing = merged[name];
      merged[name] = existing
        ? {
            outline: definition.outline ?? existing.outline,
            solid: definition.solid ?? existing.solid,
          }
        : definition;
    }
  }

  return merged;
}

export interface WiResolvedIcon {
  readonly glyph: NonNullable<WiIconDefinition['outline']>;
  readonly usedVariant: WiIconVariant;
  readonly fellBack: boolean;
}

/**
 * Resuelve el glifo para una variante solicitada.
 * Fallback: variante pedida → la otra → `null`.
 */
export function resolveIconGlyph(
  definition: WiIconDefinition | undefined,
  variant: WiIconVariant,
): WiResolvedIcon | null {
  if (!definition) {
    return null;
  }

  const preferred = definition[variant];
  if (preferred) {
    return { glyph: preferred, usedVariant: variant, fellBack: false };
  }

  const fallbackVariant: WiIconVariant = variant === 'outline' ? 'solid' : 'outline';
  const fallback = definition[fallbackVariant];
  if (fallback) {
    return { glyph: fallback, usedVariant: fallbackVariant, fellBack: true };
  }

  return null;
}

export type WiSelectSize = 'sm' | 'md' | 'lg';

/** Compara el valor de una opción con el valor seleccionado del form. */
export type WiSelectCompareWith<T = unknown> = (
  optionValue: T,
  selectedValue: T | null | undefined,
) => boolean;

/** Contexto del template de ítem (`ng-template wiSelectItem`). */
export interface WiSelectItemContext<TOption = unknown, TValue = unknown> {
  $implicit: TOption;
  option: TOption;
  value: TValue;
}

/** Contexto del template del valor seleccionado (`ng-template wiSelectSelected`). */
