import { Component, computed, inject, input, isDevMode } from '@angular/core';

import { mergeIconRegistries, resolveIconGlyph } from './wi-icon.registry';
import { WI_ICONS } from './wi-icon.tokens';
import type { WiIconSize, WiIconVariant, WiSvgNode } from './wi-icon.types';

/** Clases Tailwind estáticas (cuando el consumidor las incluye en el CSS). */
const ICON_SIZE_CLASSES: Record<WiIconSize, string> = {
  xs: 'size-3',
  sm: 'size-4',
  md: 'size-5',
  lg: 'size-6',
  xl: 'size-8',
};

/** Tamaño intrínseco del SVG (visible aunque no haya Tailwind cargado). */
const ICON_SIZE_PX: Record<WiIconSize, number> = {
  xs: 12,
  sm: 16,
  md: 20,
  lg: 24,
  xl: 32,
};

const warnedMissing = new Set<string>();
const warnedFallback = new Set<string>();

/**
 * Icono tipográfico (`wi-icon`).
 *
 * - Color: `currentColor` (p. ej. `class="text-destructive"`).
 * - Sin `label`: decorativo (`aria-hidden="true"`).
 * - Con `label`: `role="img"` + `aria-label`.
 */
@Component({
  selector: 'wi-icon',
  host: {
    class: 'wi-icon inline-block shrink-0 text-current leading-none',
  },
  template: `
    @if (resolved(); as icon) {
      <svg
        [attr.viewBox]="icon.glyph.viewBox"
        [attr.width]="sizePx()"
        [attr.height]="sizePx()"
        [attr.fill]="svgFill()"
        [attr.stroke]="svgStroke()"
        [attr.stroke-width]="svgStrokeWidth()"
        [attr.aria-hidden]="decorative() ? 'true' : null"
        [attr.role]="decorative() ? null : 'img'"
        [attr.aria-label]="decorative() ? null : label()"
        [class]="sizeClass()"
        class="block"
      >
        @for (node of icon.glyph.nodes; track $index) {
          @switch (node.tag) {
            @case ('path') {
              <path
                [attr.d]="attr(node, 'd')"
                [attr.fill]="attr(node, 'fill')"
                [attr.fill-rule]="attr(node, 'fill-rule')"
                [attr.clip-rule]="attr(node, 'clip-rule')"
                [attr.stroke]="attr(node, 'stroke')"
                [attr.stroke-width]="attr(node, 'stroke-width')"
                [attr.stroke-linecap]="attr(node, 'stroke-linecap')"
                [attr.stroke-linejoin]="attr(node, 'stroke-linejoin')"
                [attr.opacity]="attr(node, 'opacity')"
                [attr.transform]="attr(node, 'transform')"
              />
            }
            @case ('circle') {
              <circle
                [attr.cx]="attr(node, 'cx')"
                [attr.cy]="attr(node, 'cy')"
                [attr.r]="attr(node, 'r')"
                [attr.fill]="attr(node, 'fill')"
                [attr.stroke]="attr(node, 'stroke')"
                [attr.opacity]="attr(node, 'opacity')"
                [attr.transform]="attr(node, 'transform')"
              />
            }
            @case ('rect') {
              <rect
                [attr.x]="attr(node, 'x')"
                [attr.y]="attr(node, 'y')"
                [attr.width]="attr(node, 'width')"
                [attr.height]="attr(node, 'height')"
                [attr.rx]="attr(node, 'rx')"
                [attr.ry]="attr(node, 'ry')"
                [attr.fill]="attr(node, 'fill')"
                [attr.stroke]="attr(node, 'stroke')"
                [attr.opacity]="attr(node, 'opacity')"
                [attr.transform]="attr(node, 'transform')"
              />
            }
            @case ('line') {
              <line
                [attr.x1]="attr(node, 'x1')"
                [attr.y1]="attr(node, 'y1')"
                [attr.x2]="attr(node, 'x2')"
                [attr.y2]="attr(node, 'y2')"
                [attr.stroke]="attr(node, 'stroke')"
                [attr.stroke-width]="attr(node, 'stroke-width')"
                [attr.stroke-linecap]="attr(node, 'stroke-linecap')"
                [attr.opacity]="attr(node, 'opacity')"
                [attr.transform]="attr(node, 'transform')"
              />
            }
            @case ('polyline') {
              <polyline
                [attr.points]="attr(node, 'points')"
                [attr.fill]="attr(node, 'fill')"
                [attr.stroke]="attr(node, 'stroke')"
                [attr.stroke-width]="attr(node, 'stroke-width')"
                [attr.stroke-linecap]="attr(node, 'stroke-linecap')"
                [attr.stroke-linejoin]="attr(node, 'stroke-linejoin')"
                [attr.opacity]="attr(node, 'opacity')"
                [attr.transform]="attr(node, 'transform')"
              />
            }
            @case ('polygon') {
              <polygon
                [attr.points]="attr(node, 'points')"
                [attr.fill]="attr(node, 'fill')"
                [attr.stroke]="attr(node, 'stroke')"
                [attr.stroke-width]="attr(node, 'stroke-width')"
                [attr.stroke-linejoin]="attr(node, 'stroke-linejoin')"
                [attr.opacity]="attr(node, 'opacity')"
                [attr.transform]="attr(node, 'transform')"
              />
            }
            @case ('g') {
              <g
                [attr.fill]="attr(node, 'fill')"
                [attr.stroke]="attr(node, 'stroke')"
                [attr.opacity]="attr(node, 'opacity')"
                [attr.transform]="attr(node, 'transform')"
              >
                @for (child of node.children ?? []; track $index) {
                  @switch (child.tag) {
                    @case ('path') {
                      <path
                        [attr.d]="attr(child, 'd')"
                        [attr.fill]="attr(child, 'fill')"
                        [attr.fill-rule]="attr(child, 'fill-rule')"
                        [attr.clip-rule]="attr(child, 'clip-rule')"
                        [attr.stroke]="attr(child, 'stroke')"
                        [attr.stroke-width]="attr(child, 'stroke-width')"
                        [attr.stroke-linecap]="attr(child, 'stroke-linecap')"
                        [attr.stroke-linejoin]="attr(child, 'stroke-linejoin')"
                        [attr.opacity]="attr(child, 'opacity')"
                        [attr.transform]="attr(child, 'transform')"
                      />
                    }
                  }
                }
              </g>
            }
          }
        }
      </svg>
    }
  `,
})
export class WiIconComponent {
  readonly name = input.required<string>();
  readonly variant = input<WiIconVariant>('outline');
  readonly size = input<WiIconSize>('md');
  readonly label = input<string | null>(null);

  private readonly registries = inject(WI_ICONS, { optional: true });
  private readonly icons = mergeIconRegistries(this.registries);

  protected readonly sizeClass = computed(() => ICON_SIZE_CLASSES[this.size()]);

  protected readonly sizePx = computed(() => ICON_SIZE_PX[this.size()]);

  protected readonly decorative = computed(() => this.label() === null);

  protected readonly resolved = computed(() => {
    const name = this.name();
    const variant = this.variant();
    const definition = this.icons[name];
    const result = resolveIconGlyph(definition, variant);

    if (!result) {
      this.warnMissing(name, variant);
      return null;
    }

    if (result.fellBack) {
      this.warnFallback(name, variant, result.usedVariant);
    }

    return result;
  });

  protected readonly svgFill = computed(() => {
    const icon = this.resolved();
    if (!icon || icon.glyph.preserveColors) {
      return null;
    }
    return icon.usedVariant === 'solid' ? 'currentColor' : 'none';
  });

  protected readonly svgStroke = computed(() => {
    const icon = this.resolved();
    if (!icon || icon.glyph.preserveColors) {
      return null;
    }
    return icon.usedVariant === 'outline' ? 'currentColor' : null;
  });

  protected readonly svgStrokeWidth = computed(() => {
    const icon = this.resolved();
    if (!icon || icon.glyph.preserveColors || icon.usedVariant !== 'outline') {
      return null;
    }
    return '1.5';
  });

  protected attr(node: WiSvgNode, key: string): string | null {
    return node.attrs[key] ?? null;
  }

  private warnMissing(name: string, variant: WiIconVariant): void {
    if (!isDevMode()) {
      return;
    }
    const key = `${name}:${variant}:missing`;
    if (warnedMissing.has(key)) {
      return;
    }
    warnedMissing.add(key);
    console.warn(`[wi-icon] Icon "${name}" is not registered. Register it with provideWiIcons().`);
  }

  private warnFallback(name: string, requested: WiIconVariant, used: WiIconVariant): void {
    if (!isDevMode()) {
      return;
    }
    const key = `${name}:${requested}:fallback:${used}`;
    if (warnedFallback.has(key)) {
      return;
    }
    warnedFallback.add(key);
    console.warn(
      `[wi-icon] Icon "${name}" has no "${requested}" variant; falling back to "${used}".`,
    );
  }
}

import {
  booleanAttribute,
  Component,
  computed,
  forwardRef,
  input,
  model,
  output,
  signal,
} from '@angular/core';
import { type ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import type { FormValueControl } from '@angular/forms/signals';

import type { WiInputSize, WiInputType } from './wi-input.types';

const BASE_CLASSES = [
  'flex',
  'w-full',
  'min-w-0',
  'rounded-control',
  'border',
  'border-outline',
  'bg-surface',
  'text-on-surface',
  'placeholder:text-on-surface-variant',
  'transition-colors',
  'outline-none',
  'focus-visible:ring-2',
  'focus-visible:ring-ring',
  'focus-visible:ring-offset-2',
  'focus-visible:ring-offset-background',
  'disabled:pointer-events-none',
  'disabled:cursor-not-allowed',
  'disabled:opacity-50',
  'read-only:bg-surface-variant',
  'aria-invalid:border-error',
  'aria-invalid:focus-visible:ring-error',
].join(' ');

const SIZE_CLASSES: Record<WiInputSize, string> = {
  sm: 'h-control-sm px-3 text-sm',
  md: 'h-control-md px-3 text-sm',
  lg: 'h-control-lg px-4 text-base',
};

let nextInputId = 0;

/**
 * Campo de texto del design system (`wi-input`).
 *
 * - Tokens semánticos y tamaños alineados con `wi-button`.
 * - `FormValueControl` para Signal Forms (`[formField]`).
 * - `ControlValueAccessor` para Reactive Forms / `ngModel`.
 * - Label, hint y error quedan fuera (composición `wi-field` prevista).
 */
@Component({
  selector: 'wi-input',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => WiInputComponent),
      multi: true,
    },
  ],
  host: {
    class: 'wi-input contents',
  },
  template: `
    <input
      [attr.id]="resolvedId()"
      [attr.name]="name() || null"
      [attr.type]="type()"
      [attr.placeholder]="placeholder() || null"
      [attr.autocomplete]="autocomplete()"
      [attr.aria-label]="ariaLabel()"
      [attr.aria-describedby]="ariaDescribedBy()"
      [attr.aria-invalid]="invalid() || null"
      [attr.aria-required]="required() || null"
      [attr.required]="required() || null"
      [class]="classes()"
      [value]="value()"
      [disabled]="isDisabled()"
      [readonly]="readonly()"
      (input)="onNativeInput($event)"
      (blur)="onNativeBlur()"
    />
  `,
})
export class WiInputComponent implements ControlValueAccessor, FormValueControl<string> {
  /** Valor del control (Signal Forms + two-way binding). */
  readonly value = model('');

  readonly size = input<WiInputSize>('md');
  readonly type = input<WiInputType>('text');
  readonly placeholder = input('');
  readonly id = input<string | undefined>(undefined);
  readonly name = input<string>('');
  readonly autocomplete = input<string | null>(null);
  readonly ariaLabel = input<string | null>(null);
  readonly ariaDescribedBy = input<string | null>(null);

  readonly disabled = input(false, { transform: booleanAttribute });
  readonly readonly = input(false, { transform: booleanAttribute });
  readonly invalid = input(false, { transform: booleanAttribute });
  readonly required = input(false, { transform: booleanAttribute });

  /** Emite en blur para Signal Forms (`debounce('blur')`, touched). */
  readonly touch = output<void>();

  private readonly generatedId = `wi-input-${++nextInputId}`;
  private readonly cvaDisabled = signal(false);

  private onChange: (value: string) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  protected readonly resolvedId = computed(() => this.id() ?? this.generatedId);

  protected readonly isDisabled = computed(() => this.disabled() || this.cvaDisabled());

  protected readonly classes = computed(() => [BASE_CLASSES, SIZE_CLASSES[this.size()]].join(' '));

  writeValue(value: string | null): void {
    this.value.set(value ?? '');
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.cvaDisabled.set(isDisabled);
  }

  protected onNativeInput(event: Event): void {
    const next = (event.target as HTMLInputElement).value;
    this.value.set(next);
    this.onChange(next);
  }

  protected onNativeBlur(): void {
    this.onTouched();
    this.touch.emit();
  }
}

components.template:
@if (!multiple()) {
  <div
    class="wi-select__root relative w-full"
    brnSelect
    brnPopover
    [disabled]="isDisabled()"
    [value]="value()"
    [itemToString]="itemToStringFn"
    [isItemEqualToValue]="compareWithFn"
    (valueChange)="onValueChange($event)"
    (closed)="onClosed()"
  >
    <div class="relative w-full">
      <button
        brnSelectTrigger
        [id]="resolvedId()"
        [forceInvalid]="invalid()"
        [class]="triggerClasses()"
        [attr.aria-label]="ariaLabel()"
        [attr.aria-describedby]="ariaDescribedBy()"
        [attr.aria-required]="required() || null"
        [attr.aria-invalid]="invalid() || null"
        [attr.name]="name() || null"
      >
        <span class="min-w-0 flex-1 truncate text-left">
          @if (hasSelection()) {
            @if (resolvedSelectedTemplate(); as selectedTpl) {
              <ng-container *ngTemplateOutlet="selectedTpl; context: selectedContext()" />
            } @else {
              {{ displayLabel() }}
            }
          } @else {
            {{ placeholder() }}
          }
        </span>
        @if (!(clearable() && hasSelection())) {
          @if (triggerIconTemplate(); as iconTpl) {
            <span
              class="wi-select__trigger-icon inline-flex size-4 shrink-0 items-center justify-center opacity-60 [&_svg]:size-4"
              aria-hidden="true"
            >
              <ng-container *ngTemplateOutlet="iconTpl" />
            </span>
          } @else if (icon(); as iconName) {
            <span
              class="wi-select__trigger-icon inline-flex size-4 shrink-0 items-center justify-center opacity-60 [&_svg]:size-4 [&_wi-icon]:size-4"
              aria-hidden="true"
            >
              <wi-icon [name]="iconName" />
            </span>
          } @else {
            <svg
              class="wi-select__chevron size-4 shrink-0 opacity-60"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="1.5"
              aria-hidden="true"
            >
              <path
                stroke-linecap="round"
                stroke-linejoin="round"
                d="m19.5 8.25-7.5 7.5-7.5-7.5"
              />
            </svg>
          }
        }
      </button>
      @if (clearable() && hasSelection()) {
        <button
          type="button"
          class="wi-select__clear absolute top-1/2 right-2 inline-flex size-6 -translate-y-1/2 items-center justify-center rounded-control text-on-surface-variant hover:bg-surface-variant hover:text-on-surface"
          [attr.aria-label]="clearLabel()"
          [disabled]="isDisabled()"
          (click)="onClear($event)"
        >
          <svg
            class="size-4"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            aria-hidden="true"
          >
            <path stroke-linecap="round" stroke-linejoin="round" d="M6 18 18 6M6 6l12 12" />
          </svg>
        </button>
      }
    </div>

    <ng-template brnPopoverContent>
      <div brnSelectContent [class]="panelClasses">
        <div brnSelectList class="wi-select__list flex flex-col p-1">
          @for (option of options(); track trackOption($index, option)) {
            <div [class]="optionClasses" brnSelectItem [value]="resolveOptionValue(option)">
              <span class="min-w-0 flex-1 truncate">
                @if (resolvedItemTemplate(); as itemTpl) {
                  <ng-container *ngTemplateOutlet="itemTpl; context: itemContext(option)" />
                } @else {
                  {{ resolveOptionLabel(option) }}
                }
              </span>
              <svg
                class="wi-select__check size-4 shrink-0 opacity-0"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="1.5"
                aria-hidden="true"
              >
