} @else {
  <div
    class="wi-select__root relative w-full"
    brnSelectMultiple
    brnPopover
    [disabled]="isDisabled()"
    [value]="multiValue()"
    [itemToString]="itemToStringFn"
    [isItemEqualToValue]="compareWithFn"
    (valueChange)="onMultiValueChange($event)"
